<template><div class="wrap"><div class="page-head"><h1>My BraTips</h1><p class="muted">Welcome back, {{auth.user?.name}}.</p></div><div class="card"><div class="section-head"><div><h2>My Picks</h2></div><button class="ghost" @click="markAll">{{unread?`Mark ${unread} read`:'Notifications read'}}</button></div><p class="muted small">Your tracked selections and potential returns.</p><div v-if="notifications.length" class="notification-list"><div v-for="n in notifications" :key="n._id" class="notice" :class="{unread:!n.read}" @click="read(n)"><b>{{n.title}}</b><p>{{n.message}}</p><small>{{new Date(n.createdAt).toLocaleString()}}</small></div></div><div v-if="picks.length" class="table-wrap"><table class="table"><thead><tr><th>Pick</th><th>Odds</th><th>Stake</th><th>Potential return</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="x in picks" :key="x._id"><td>{{x.predictionId?.fixture}}<br/><span class="muted small">{{x.predictionId?.prediction}}</span></td><td>{{Number(x.predictionId?.odds||0).toFixed(2)}}</td><td>GHS {{Number(x.stake).toFixed(2)}}</td><td>GHS {{Number(x.potentialReturn).toFixed(2)}}</td><td>{{x.status}}</td><td><button v-if="x.status==='open'" class="ghost" @click="remove(x._id)">Remove</button></td></tr></tbody></table></div><div v-else class="empty">No picks yet. <RouterLink to="/picks" style="color:var(--pink);font-weight:800">Browse tipster picks →</RouterLink></div></div><div class="section" v-if="auth.isTipster"><div class="section-head"><h2>Tipster tools</h2></div><div class="grid2"><form class="card" @submit.prevent="submitPrediction"><h3>Submit a prediction</h3><p class="muted small">New predictions go to admin review before publishing.</p><div class="field"><label>Fixture</label><input v-model="form.fixture" required/></div><div class="grid2"><div class="field"><label>Prediction</label><input v-model="form.prediction" required/></div><div class="field"><label>Odds</label><input v-model.number="form.odds" type="number" min="1" step=".01" required/></div></div><div class="field"><label>Confidence</label><input v-model.number="form.confidence" type="number" min="0" max="100"/></div><div class="field"><label>Analysis</label><textarea v-model="form.analysis"/></div><button class="btn">Submit for review</button><div v-if="message" class="success" style="margin-top:10px">{{message}}</div></form><div class="card"><h3>Your tipster record</h3><div v-if="tipster"><div class="kpis"><div class="stat"><span class="muted small">Tips</span><b>{{tipster.totalTips}}</b></div><div class="stat"><span class="muted small">Wins</span><b>{{tipster.wins}}</b></div><div class="stat"><span class="muted small">Streak</span><b>{{tipster.currentStreak||0}}</b></div><div class="stat"><span class="muted small">Best</span><b>{{tipster.longestStreak||0}}</b></div></div></div></div></div></div><div class="section" style="padding-top:10px"><div class="grid3"><RouterLink class="card" to="/matches"><b>Matches & Live</b><p class="muted small">Follow today’s fixtures and scores.</p></RouterLink><RouterLink class="card" to="/picks"><b>Browse picks</b><p class="muted small">Explore published predictions.</p></RouterLink><RouterLink class="card" to="/bet-of-the-day"><b>Bet of the Day</b><p class="muted small">See today's featured picks.</p></RouterLink><RouterLink class="card" to="/history"><b>Track record</b><p class="muted small">Review settled results.</p></RouterLink></div></div></div></template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {RouterLink} from 'vue-router';import {useAuth} from '../stores/auth';import {api} from '../services/api';const auth=useAuth(),picks=ref<any[]>([]),tipster=ref<any>(null),message=ref(''),notifications=ref<any[]>([]),unread=ref(0);const form=reactive<any>({fixture:'',prediction:'',odds:1.5,confidence:80,analysis:''});async function load(){try{const n=await api.get('/me/notifications');notifications.value=n.data||[];unread.value=n.unread||0}catch{} try{picks.value=(await api.get('/me/picks')).data}catch{}if(auth.isTipster)try{const d=await api.get('/me/tipster');tipster.value=d.data.profile}catch{}}async function read(n:any){if(!n.read){await api.patch(`/me/notifications/${n._id}/read`,{});n.read=true;unread.value=Math.max(0,unread.value-1)}} async function markAll(){await api.patch('/me/notifications/read-all',{});notifications.value.forEach(n=>n.read=true);unread.value=0} async function remove(id:string){await api.delete?.(`/me/picks/${id}`);await load()}async function submitPrediction(){try{const d=await api.post('/me/tipster/predictions',form);message.value=d.message;Object.assign(form,{fixture:'',prediction:'',odds:1.5,confidence:80,analysis:''})}catch(e:any){message.value=e.message}}onMounted(load)</script>
